import fs from 'node:fs';import path from 'node:path';import {setup} from './node-host.mjs';import {FomkyrEngine} from '../web/engine.js';import {stats} from '../web/runtime.js';
const [fixture='fixtures/fk6.json',d='9',settings='{}',out='/mnt/data/reserve-probe063']=process.argv.slice(2);fs.mkdirSync(out,{recursive:true});setup(path.join(out,'storage'));
let e=new FomkyrEngine({workers:4,bits:32,budgetBytes:128<<20,scratchBytes:4<<20,rowReserveBytes:32<<20,spill:true,resume:false,runKey:'probe',progress:false,exportText:false,hilbert:false,radixHeap:true,timeoutMs:30000,...JSON.parse(settings)});let report={settings:JSON.parse(settings)};
const t=performance.now();try{let x=await e.compute(JSON.parse(fs.readFileSync(fixture)),Number(d),0);report.result={...x,preview:undefined};report.status='complete';}catch(x){report.error=String(x);report.code=x.code;report.status='incomplete';report.stats=stats(e.e);}finally{report.elapsedMs=performance.now()-t;await e.close();fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({status:report.status,error:report.error,...(report.result??report.stats),preview:undefined,degreeTimings:undefined}));}
